fn max(a: &Vec<i32>, n: usize) -> i32 {
    // We assume: n > 0, n <= a.len(), and n < 1000
    // Initialize the maximum with the first element
    let mut current_max = a[0];

    // Iterate over the remaining elements in the prefix [1..n)
    for i in 1..n {
        if a[i] > current_max {
            current_max = a[i];
        }
    }

    current_max
}

fn main() {
    let v = vec![3, 7, 2, 9, 5];
    assert_eq!(max(&v, 1), 3);
    assert_eq!(max(&v, 2), 7);
    assert_eq!(max(&v, 3), 7);
    assert_eq!(max(&v, 4), 9);
    assert_eq!(max(&v, 5), 9);

    println!("All tests passed!");
}